// The 7 official PlacidWay pages. Everything the bot knows comes from here.
const pages = [
  { name: 'profile', url: 'https://www.placidway.com/profile/5/Alternative-Cancer-Treatment-by-ITC-Immunity-Therapy-Center' },
  { name: 'adenocarcinoma-package', url: 'https://www.placidway.com/package/7903/Alternative-Adenocarcinoma-Cancer-Treatment-Package-in-Tijuana-Mexico-by-ITC' },
  { name: 'adrenal-package', url: 'https://www.placidway.com/package/7902/Alternative-Adrenal-Cancer-Treatment-Package-in-Tijuana-Mexico-by-ITC' },
  { name: 'anal-package', url: 'https://www.placidway.com/package/7901/Alternative-Anal-Cancer-Treatment-Package-in-Tijuana-Mexico-by-ITC' },
  { name: 'videos', url: 'https://www.placidway.com/profile-videos/5/Alternative-Cancer-Treatment-by-ITC-Immunity-Therapy-Center' },
  { name: 'price-list', url: 'https://www.placidway.com/price-list/5/Alternative-Cancer-Treatment-by-ITC-Immunity-Therapy-Center' },
  { name: 'search-pricing', url: 'https://www.placidway.com/search-medical-pricings/Alternative-Medicine/All/1' }
];
return pages.map(p => ({ json: p }));

// Strip HTML and split each page into ~1200-char chunks (150 overlap).
const pages = $('List pages').all().map(i => i.json);
const htmls = $input.all().map(i => i.json);
const out = [];
for (let k = 0; k < htmls.length; k++) {
  const html = String(htmls[k].data || '');
  const page = pages[k] || {};
  let t = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
  t = t.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
  for (let s = 0; s < t.length; s += 1050) {
    const c = t.slice(s, s + 1200).trim();
    if (c.length > 100) out.push({ json: { source_name: page.name, source_url: page.url, content: c } });
  }
}
return out;

// Pair each embedding with the chunk it came from.
const chunk = $('Clean & chunk').item.json;
const values = $json.data.embedding.values;
return [{ json: { content: chunk.content, source_url: chunk.source_url, source_name: chunk.source_name, embedding: values } }];
